def membership_notification_recipients():
    """إشعارات العضوية تذهب حصريًا إلى المالك الأساسي ونواب المالك المسجلين."""
    recipients = {int(OWNER_ID)} if OWNER_ID else set()
    recipients.update(
        int(row[0]) for row in db.execute("SELECT user_id FROM deputy_owners")
        if int(row[0]) > 0
    )
    return recipients


async def notify_owners(context, text, event="general"):
    # إشعارات العضوية محصورة بالمالك الأساسي ونوابه؛ بقية الأحداث تتبع مستلميها المحددين.
    if event == "membership":
        recipients = membership_notification_recipients()
    else:
        recipients = {OWNER_ID} if OWNER_ID else set()
        recipients.update(int(r[0]) for r in db.execute("SELECT user_id FROM delegated_owners"))
    for recipient in recipients:
        pref = db.execute("SELECT enabled FROM notification_preferences WHERE user_id=? AND event=?", (recipient, event)).fetchone()
        if pref and not pref[0]:
            continue
        try:
            await context.bot.send_message(chat_id=recipient, text=text)
        except Exception as exc:
            log.info("تعذر إرسال إشعار إلى %s: %s", recipient, exc)


async def notify_owner_and_deputies(context, text, reply_markup=None):
    """إشعارات الدخول وطلبات الانضمام للمالك الأساسي ونواب المالك فقط."""
    for recipient in membership_notification_recipients():
        try:
            await context.bot.send_message(chat_id=recipient, text=text, reply_markup=reply_markup)
        except Exception as exc:
            log.info("تعذر إرسال إشعار العضوية إلى %s: %s", recipient, exc)


async def notify_group_stakeholders(context, chat_id, text):
    """Notify the verified Telegram group creator plus the bot owner and deputies.

    Only known Telegram creator IDs are used; transient API failures never broaden recipients.
    """
    recipients = set(membership_notification_recipients())
    row = db.execute("SELECT telegram_owner_id FROM external_group_control WHERE chat_id=?", (int(chat_id),)).fetchone()
    group_owner_id = int(row[0] or 0) if row else 0
    if not group_owner_id:
        try:
            admins = await context.bot.get_chat_administrators(int(chat_id))
            creator = next((item.user for item in admins if getattr(item, "status", "") == "creator"), None)
            group_owner_id = int(creator.id) if creator else 0
            if group_owner_id:
                db.execute("UPDATE external_group_control SET telegram_owner_id=? WHERE chat_id=?", (group_owner_id, int(chat_id)))
                db.commit()
        except Exception as exc:
            log.debug("Could not resolve group creator for notifications chat=%s: %s", chat_id, exc)
    if group_owner_id > 0:
        recipients.add(group_owner_id)
    for recipient in sorted(recipients):
        try:
            await context.bot.send_message(chat_id=recipient, text=text, disable_web_page_preview=True)
        except Exception as exc:
            log.info("تعذر إرسال إشعار القروب %s إلى %s: %s", chat_id, recipient, exc)

def archive_is_enabled(chat_id):
    row = db.execute("SELECT enabled FROM archive_settings WHERE chat_id=?", (chat_id,)).fetchone()
    return bool(row and row[0])

async def archive_on(update, context):
    if not is_owner(update.effective_user.id):
        await update.effective_message.reply_text("⛔ هذا الأمر للمالك الأساسي فقط.")
        return
    chat = update.effective_chat
    if not chat or chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        await update.effective_message.reply_text("استخدم الأمر داخل المجموعة التي تريد تفعيل الأرشفة فيها.")
        return
    register_group(chat)
    db.execute("INSERT OR REPLACE INTO archive_settings(chat_id,enabled) VALUES(?,1)", (chat.id,))
    db.commit()
    await update.effective_message.reply_text(
        "⚠️ تم تفعيل تسجيل الرسائل الجديدة لهذه المجموعة.\n"
        "يرجى إعلان ذلك لأعضاء المجموعة وفق قواعدها. أرسل /archive_off لإيقاف التسجيل."
    )

async def archive_off(update, context):
    if not is_owner(update.effective_user.id):
        await update.effective_message.reply_text("⛔ هذا الأمر للمالك الأساسي فقط.")
