def owner_autoreply_group_markup(chat_id):
    rows = db.execute("SELECT trigger_text,reply_text,enabled FROM auto_replies WHERE chat_id=? ORDER BY trigger_text", (chat_id,)).fetchall()
    buttons = [
        [InlineKeyboardButton("➕ إضافة رد جديد", callback_data=f"owner_ar_add:{chat_id}")],
        [InlineKeyboardButton("✏️ تعديل رد موجود", callback_data=f"owner_ar_edit:{chat_id}")],
        [InlineKeyboardButton("🗑️ حذف رد", callback_data=f"owner_ar_delete:{chat_id}")],
        [InlineKeyboardButton("🔄 تشغيل الردود", callback_data=f"owner_ar_on:{chat_id}"), InlineKeyboardButton("⏸️ إيقاف الردود", callback_data=f"owner_ar_off:{chat_id}")],
        [InlineKeyboardButton("⬅️ القروبات", callback_data="owner_autoreplies")]
    ]
    return rows, buttons

async def owner_autoreply_text_handler(update, context):
    """Receives auto-reply setup text, while reserving AI status aliases."""
    if not update.effective_user or not update.effective_message or update.effective_chat.type != ChatType.PRIVATE:
        return
    raw = (update.effective_message.text or "").strip()
    # Let the owner check AI status even while an auto-reply wizard is waiting for input.
    if _is_aistatus_alias(raw):
        await aistatus_cmd(update, context)
        return
    state = context.user_data.get("owner_autoreply_state")
    if not state:
        return
    if not (is_owner(update.effective_user.id) or is_delegated_owner(update.effective_user.id)):
        context.user_data.pop("owner_autoreply_state", None)
        return
    raw = (update.effective_message.text or "").strip()
    if not raw or raw.startswith("/"):
        await update.effective_message.reply_text("أرسل النص المطلوب بدون أمر. أرسل /cancel لإلغاء العملية.")
        return
    if raw.lower() == "/cancel":
        context.user_data.pop("owner_autoreply_state", None)
        await update.effective_message.reply_text("تم إلغاء العملية.")
        return
    action = state["action"]
    if action in ("add_all", "edit_all", "delete_all"):
        groups = [r[0] for r in db.execute("SELECT chat_id FROM watched_groups ORDER BY title").fetchall()]
        if not groups:
            context.user_data.pop("owner_autoreply_state", None)
            await update.effective_message.reply_text("لا توجد قروبات مسجلة لتطبيق التغيير عليها.")
            return
        if action == "delete_all":
            trigger = raw.strip()
            if not trigger or len(trigger) > 100:
                await update.effective_message.reply_text("أرسل عبارة صحيحة لا تتجاوز 100 حرف.")
                return
            deleted = 0
            for group_id in groups:
                cur = db.execute("DELETE FROM auto_replies WHERE chat_id=? AND trigger_text=?", (group_id, trigger))
                deleted += cur.rowcount
                if cur.rowcount:
                    log_action(group_id, update.effective_user.id, "auto_reply_deleted", trigger)
            db.commit()
            context.user_data.pop("owner_autoreply_state", None)
            await update.effective_message.reply_text(f"🗑️ اكتمل الحذف من جميع القروبات المسجلة. عدد السجلات المحذوفة: {deleted}.")
            return
        if "|" not in raw:
            await update.effective_message.reply_text("أرسل العبارة والرد بهذا الشكل:\nالعبارة | الرد")
            return
        trigger, reply = (x.strip() for x in raw.split("|", 1))
        if not trigger or not reply or len(trigger) > 100 or len(reply) > 1000:
            await update.effective_message.reply_text("تأكد من كتابة العبارة والرد، بحد أقصى 100 حرف للعبارة و1000 للرد.")
            return
        if action == "edit_all":
            found = any(db.execute("SELECT 1 FROM auto_replies WHERE chat_id=? AND trigger_text=?", (group_id, trigger)).fetchone() for group_id in groups)
            if not found:
                context.user_data.pop("owner_autoreply_state", None)
                await update.effective_message.reply_text("لم أجد العبارة في أي قروب. استخدم الإضافة للتعميم أو أعد المحاولة بعبارة موجودة.")
                return
        for group_id in groups:
            ensure_auto_replies(group_id)
            db.execute(
                "INSERT INTO auto_replies(chat_id,trigger_text,reply_text,enabled) VALUES(?,?,?,1) "
                "ON CONFLICT(chat_id,trigger_text) DO UPDATE SET reply_text=excluded.reply_text,enabled=1",
                (group_id, trigger, reply))
            db.execute("UPDATE auto_reply_settings SET enabled=1 WHERE chat_id=?", (group_id,))
            log_action(group_id, update.effective_user.id, "auto_reply_added" if action == "add_all" else "auto_reply_edited", trigger)
        db.commit()
        context.user_data.pop("owner_autoreply_state", None)
        await update.effective_message.reply_text(
            f"✅ تم {'تعميم' if action == 'add_all' else 'تعديل وتعميم'} الرد على جميع القروبات المسجلة ({len(groups)}).\n\n"
            f"🗣️ العبارة: {trigger}\n💬 الرد: {reply}\n\n"
            "ملاحظة: تم حفظ الإعدادات في قاعدة البيانات؛ يجب أن تكون القروبات مسجلة في البوت.")
        return

    chat_id = int(state["chat_id"])
    if action in ("add", "edit"):
        if " | " not in raw and "|" not in raw:
            await update.effective_message.reply_text("أرسل العبارة والرد بهذا الشكل:\nالعبارة | الرد الذي سيظهر في القروب")
            return
        trigger, reply = (x.strip() for x in raw.split("|", 1))
        if not trigger or not reply or len(trigger) > 100 or len(reply) > 1000:
            await update.effective_message.reply_text("تأكد من كتابة العبارة والرد، بحد أقصى 100 حرف للعبارة و1000 للرد.")
            return
        ensure_auto_replies(chat_id)
        existing = db.execute("SELECT trigger_text FROM auto_replies WHERE chat_id=?", (chat_id,)).fetchall()
        matched = next((row[0] for row in existing if normalize_auto_reply(row[0]) == normalize_auto_reply(trigger)), None)
        if action == "edit" and not matched:
            await update.effective_message.reply_text("لم أجد عبارة مطابقة للتعديل. افتح إدارة الردود واختر عبارة موجودة.")
            context.user_data.pop("owner_autoreply_state", None)
            return
        if matched and action == "edit":
            db.execute("UPDATE auto_replies SET reply_text=?,enabled=1 WHERE chat_id=? AND trigger_text=?", (reply, chat_id, matched))
            trigger = matched
            event = "auto_reply_edited"
        else:
            db.execute("INSERT INTO auto_replies(chat_id,trigger_text,reply_text,enabled) VALUES(?,?,?,1) ON CONFLICT(chat_id,trigger_text) DO UPDATE SET reply_text=excluded.reply_text,enabled=1", (chat_id, trigger, reply))
            event = "auto_reply_added"
        db.execute("INSERT OR IGNORE INTO auto_reply_settings(chat_id,enabled) VALUES(?,1)", (chat_id,))
        db.execute("UPDATE auto_reply_settings SET enabled=1 WHERE chat_id=?", (chat_id,))
        db.commit()
        log_action(chat_id, update.effective_user.id, event, trigger)
        context.user_data.pop("owner_autoreply_state", None)
        await update.effective_message.reply_text(f"✅ تم {'تعديل' if action == 'edit' else 'إضافة'} الرد وتفعيله في القروب.\n\n🗣️ العبارة: {trigger}\n💬 الرد: {reply}")
        return
    context.user_data.pop("owner_autoreply_state", None)


async def cancel_owner_autoreply(update, context):
    keys = ("owner_autoreply_state", "awaiting_motivation_edit", "awaiting_general_inquiry", "inquiry_reply_id", "awaiting_channel_broadcast", "channel_broadcast_draft", "channel_broadcast_selected", "awaiting_staff_permissions_id", "awaiting_delegated_owner_id", "awaiting_unified_target_id", "awaiting_warning_grant", "awaiting_warning_log_search", "awaiting_archive_search", "awaiting_calendar_search", "awaiting_admin_action", "awaiting_broadcast", "broadcast_draft", "broadcast_selected_groups", "awaiting_welcome_chat", "external_support_state", "awaiting_group_broadcast", "group_broadcast_draft", "support_reply_ticket_id", "mass_ban_state", "massban_selected_groups", "awaiting_admin_action", "staff_task_state", "staff_shift_state", "staff_badge_state", "awaiting_channel_broadcast")
    cancelled = False
    for key in keys:
        if context.user_data.pop(key, None) is not None:
            cancelled = True
    await update.effective_message.reply_text("تم إلغاء العملية الحالية." if cancelled else "لا توجد عملية قيد التنفيذ.")


class HealthHandler(BaseHTTPRequestHandler):
    def _json(self, status, obj):
        raw = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(status); self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store"); self.send_header("Content-Length", str(len(raw)))
        self.end_headers(); self.wfile.write(raw)
    def _body(self):
        length = min(int(self.headers.get("Content-Length", "0") or 0), 1_000_000)
        return json.loads(self.rfile.read(length).decode("utf-8") or "{}")
    def _user_id(self):
        # Verify Telegram Mini App initData using Telegram's documented HMAC scheme.
        init_data = self.headers.get("X-Telegram-Init-Data", "")
        if not TOKEN or not init_data: return None
        from urllib.parse import parse_qsl
        pairs = dict(parse_qsl(init_data, keep_blank_values=True))
        supplied = pairs.pop("hash", None)
        if not supplied: return None
        import hashlib, hmac
        check = "\n".join(f"{k}={v}" for k,v in sorted(pairs.items()))
        secret = hmac.new(b"WebAppData", TOKEN.encode(), hashlib.sha256).digest()
        expected = hmac.new(secret, check.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, supplied): return None
        try:
            auth_date = int(pairs.get("auth_date", "0"))
            if abs(int(time.time()) - auth_date) > 86400: return None
            user = json.loads(pairs.get("user", "{}"))
            uid = int(user["id"])
            return uid if uid > 0 else None
        except Exception: return None
    def do_GET(self):
        from urllib.parse import urlparse
        path = urlparse(self.path).path
        if path == "/health":
            raw=b"Telegram bot is running."; self.send_response(200); self.send_header("Content-Type","text/plain; charset=utf-8"); self.end_headers(); self.wfile.write(raw); return
        self.send_error(404)
    def do_POST(self):
        from urllib.parse import urlparse
        path=urlparse(self.path).path; uid=self._user_id()
        if not uid: self._json(401,{"error":"تعذر التحقق من تيليجرام؛ افتح الواجهة من زر البوت."}); return
        try: data=self._body()
        except Exception: self._json(400,{"error":"بيانات الطلب غير صالحة."}); return
        now=datetime.now(timezone.utc).isoformat(timespec="seconds")
        if path == "/api/staff/panel":
            if not (is_owner(uid) or is_delegated_owner(uid) or is_general_manager(uid)):
                self._json(403,{"error":"هذه اللوحة مخصصة لفريق الإدارة."}); return
            owner=is_owner(uid); role="المالك الأساسي" if owner else ("المالك المفوض" if is_delegated_owner(uid) else "مدير")
            groups=[{"id":int(cid),"title":title} for cid,title in db.execute("SELECT chat_id,title FROM watched_groups ORDER BY title")]
            rows=db.execute("SELECT capability,chat_id FROM staff_capabilities WHERE user_id=? ORDER BY capability,chat_id",(uid,)).fetchall()
            my_caps=[{"capability":cap,"chat_id":int(cid),"label":STAFF_CAPABILITY_LABELS.get(cap,cap),"group_title":next((g["title"] for g in groups if g["id"]==int(cid)),"")} for cap,cid in rows]
            self._json(200,{"owner":owner,"role":role,"capabilities":STAFF_CAPABILITY_LABELS,"groups":groups,"my_capabilities":my_caps}); return
        if path == "/api/staff/target":
            if not is_owner(uid): self._json(403,{"error":"إدارة الصلاحيات متاحة للمالك الأساسي فقط."}); return
            try: target=int(data.get("target_uid",0))
            except Exception: self._json(400,{"error":"رقم المستخدم غير صحيح."}); return
            groups={int(cid):title for cid,title in db.execute("SELECT chat_id,title FROM watched_groups")}
            grants=[{"capability":cap,"chat_id":int(cid),"group_title":groups.get(int(cid),"")} for cap,cid in db.execute("SELECT capability,chat_id FROM staff_capabilities WHERE user_id=? ORDER BY capability,chat_id",(target,)).fetchall()]
            self._json(200,{"grants":grants}); return
        if path == "/api/staff/grant":
            if not is_owner(uid): self._json(403,{"error":"منح الصلاحيات وسحبها متاح للمالك الأساسي فقط."}); return
            try:
                target=int(data.get("target_uid",0)); cap=str(data.get("capability","")); scope=int(data.get("chat_id",0)); enabled=bool(data.get("enabled"))
                if target<=0 or target==OWNER_ID or is_delegated_owner(target) or cap not in STAFF_CAPABILITY_LABELS: raise ValueError
                if scope and not db.execute("SELECT 1 FROM watched_groups WHERE chat_id=?",(scope,)).fetchone(): self._json(400,{"error":"القروب غير مسجل في البوت."}); return
                if enabled:
                    db.execute("DELETE FROM staff_capability_denials WHERE user_id=? AND capability=? AND chat_id=?",(target,cap,scope))
                    db.execute("INSERT OR REPLACE INTO staff_capabilities(user_id,capability,chat_id,granted_by,granted_at) VALUES(?,?,?,?,?)",(target,cap,scope,uid,now()))
                else:
                    db.execute("DELETE FROM staff_capabilities WHERE user_id=? AND capability=? AND chat_id=?",(target,cap,scope))
                    if scope==0: db.execute("DELETE FROM staff_capability_denials WHERE user_id=? AND capability=?",(target,cap))
                db.commit(); log_action(scope,uid,"miniapp_staff_capability_changed",f"target={target};capability={cap};enabled={int(enabled)}")
                self._json(200,{"ok":True,"message":"✅ تم تحديث الصلاحية وحفظها."}); return
            except Exception: self._json(400,{"error":"تعذر تحديث الصلاحية؛ تحقق من رقم المستخدم والصلاحية."}); return
        self.send_error(404)
    def log_message(self, format, *args): return

def start_health_server():
    port = int(os.environ.get("PORT", "10000"))
    ThreadingHTTPServer(("0.0.0.0", port), HealthHandler).serve_forever()

def _group_report_metrics(chat_id, title):
    """Build a privacy-minimized report from aggregates, protection settings and operational logs."""
    since = (datetime.now(timezone.utc) - __import__("datetime").timedelta(hours=24)).isoformat(timespec="seconds")
    week = _week_start()
    try:
        messages = db.execute("SELECT COALESCE(SUM(message_count),0),COUNT(DISTINCT user_id) FROM weekly_message_activity WHERE chat_id=? AND week_start=?", (chat_id, week)).fetchone()
        weekly_messages, weekly_active = int(messages[0] or 0), int(messages[1] or 0)
        actions = db.execute("SELECT action,COUNT(*) FROM logs WHERE chat_id=? AND created_at>=? GROUP BY action ORDER BY COUNT(*) DESC LIMIT 8", (chat_id, since)).fetchall()
        incidents = db.execute("SELECT COUNT(*) FROM logs WHERE chat_id=? AND created_at>=? AND (LOWER(COALESCE(action,'')) LIKE '%ban%' OR LOWER(COALESCE(action,'')) LIKE '%mute%' OR LOWER(COALESCE(action,'')) LIKE '%delete%' OR LOWER(COALESCE(action,'')) LIKE '%kick%' OR LOWER(COALESCE(action,'')) LIKE '%error%' OR LOWER(COALESCE(action,'')) LIKE '%fail%')", (chat_id, since)).fetchone()[0]
        known = db.execute("SELECT COUNT(DISTINCT user_id) FROM member_activity WHERE chat_id=?", (chat_id,)).fetchone()[0]
        recent = db.execute("SELECT COUNT(*) FROM logs WHERE chat_id=? AND created_at>=?", (chat_id, since)).fetchone()[0]
        joins = db.execute("SELECT COUNT(*) FROM weekly_membership_events WHERE chat_id=? AND event_type='join' AND substr(event_at,1,10)>=?", (chat_id, week)).fetchone()[0]
        leaves = db.execute("SELECT COUNT(*) FROM weekly_membership_events WHERE chat_id=? AND event_type='leave' AND substr(event_at,1,10)>=?", (chat_id, week)).fetchone()[0]
        settings = get_settings(chat_id)
        protection_state = {name: bool(settings.get(name, 0)) for name in ("links", "photos", "videos", "audio", "files", "stickers", "flood", "verify_new_members")}
        # Privacy-preserving anomaly signals: counts and message-volume thresholds only, no member IDs.
        volume_rows = db.execute("SELECT message_count FROM weekly_message_activity WHERE chat_id=? AND week_start=? ORDER BY message_count DESC LIMIT 5", (chat_id, week)).fetchall()
        top = [(f"عضو {idx}", int(row[0] or 0)) for idx, row in enumerate(volume_rows, 1)]
        high_activity_members = int(db.execute("SELECT COUNT(*) FROM weekly_message_activity WHERE chat_id=? AND week_start=? AND message_count>=100", (chat_id, week)).fetchone()[0] or 0)
        max_member_messages = max((int(row[0] or 0) for row in volume_rows), default=0)
        violation_row = db.execute("SELECT COUNT(*),COALESCE(SUM(warning_count),0) FROM member_violations WHERE chat_id=? AND last_at>=?", (chat_id, since)).fetchone()
        recent_violating_members = int((violation_row or (0,0))[0] or 0)
        recent_warning_total = int((violation_row or (0,0))[1] or 0)
    except Exception:
        log.exception("Group report metrics failed for %s", chat_id)
        weekly_messages, weekly_active, incidents, known, recent, actions, top, joins, leaves = 0, 0, 0, 0, 0, [], [], 0, 0
        high_activity_members, max_member_messages, recent_violating_members, recent_warning_total = 0, 0, 0, 0
        protection_state = {}
    return {"chat_id": chat_id, "title": title or str(chat_id), "weekly_messages": weekly_messages,
            "weekly_active_members": weekly_active, "known_members": int(known or 0),
            "weekly_joins": int(joins or 0), "weekly_leaves": int(leaves or 0),
            "high_activity_members_100plus_messages": high_activity_members,
            "max_messages_by_one_member": max_member_messages,
            "members_with_recent_violations": recent_violating_members,
            "recent_warning_total": recent_warning_total,
            "protection_state": protection_state,
            "recent_admin_actions_24h": int(recent or 0), "incident_like_actions_24h": int(incidents or 0),
            "action_breakdown": [{"action": a, "count": c} for a, c in actions],
            "top_active_members": [{"name": n, "messages": c} for n, c in top]}


async def _ai_analyze_group_metrics(metrics):
    """Optional generative analysis; sends aggregate metrics only, never archived message text."""
    if not OPENAI_API_KEY:
        return ""
    safe_metrics = {key: value for key, value in metrics.items() if key not in {"chat_id", "title"}}
    prompt = (
        "أنت محلل تشغيلي لبوت إدارة قروبات تيليجرام. حلل البيانات الرقمية المجمعة التالية فقط. "
        "لا تخترع معلومات أو تتهم أعضاء، واذكر محدودية البيانات وأنها مرصودة منذ تشغيل البوت. "
        "أعط ملخصًا موجزًا ومؤشرات تحتاج متابعة وتوصيات عملية بالعربية. لا تقترح عقوبة تلقائية.\n"
        + json.dumps(safe_metrics, ensure_ascii=False)
    )
    try:
        async with httpx.AsyncClient(timeout=20.0) as client:
            response = await client.post(
                "https://api.openai.com/v1/chat/completions",
                headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"},
                json={"model": OPENAI_MODEL, "messages": [{"role": "system", "content": "كن دقيقًا ومتحفظًا؛ لا تستنتج إساءة من الأرقام وحدها."}, {"role": "user", "content": prompt}], "temperature": 0.2, "max_tokens": 450}
            )
            response.raise_for_status()
            data = response.json()
            return str(data["choices"][0]["message"]["content"]).strip()[:2500]
    except Exception as exc:
        log.warning("AI group analysis failed: %s", exc)
        return ""


def _local_group_insights(metrics):
    notes = []
    if metrics["weekly_messages"] == 0:
        notes.append("النشاط غير ظاهر في بيانات هذا الأسبوع؛ تحقق من استقبال الرسائل أو حداثة تسجيل القروب.")
    if metrics["incident_like_actions_24h"] >= 10:
        notes.append("عدد إجراءات الإشراف المرصودة مرتفع نسبيًا؛ راجع السجل للتأكد من عدم وجود إغراق أو أخطاء متكررة.")
    if metrics["weekly_messages"] >= 1000 and metrics["weekly_active_members"] > 0 and metrics["weekly_messages"] / metrics["weekly_active_members"] >= 100:
        notes.append("متوسط الرسائل لكل عضو نشط مرتفع؛ افحص احتمالات التكرار أو الإغراق يدويًا قبل اتخاذ أي إجراء.")
    if metrics.get("weekly_joins", 0) >= 20:
        notes.append("لوحظ ارتفاع في انضمام الأعضاء هذا الأسبوع؛ راجع سجل الانضمام وإعدادات روابط الدعوة.")
    if metrics.get("high_activity_members_100plus_messages", 0) >= 3:
        notes.append("هناك عدة حسابات تجاوزت 100 رسالة هذا الأسبوع؛ راجع سياق الرسائل وسجلات التكرار قبل الحكم بوجود إغراق.")
    if metrics.get("members_with_recent_violations", 0) >= 5 or metrics.get("recent_warning_total", 0) >= 10:
        notes.append("توجد مخالفات/إنذارات مسجلة مؤخرًا؛ راجع الأسباب المسجلة يدويًا ولا تعتمد على العدد وحده لاتخاذ عقوبة.")
    if metrics["weekly_active_members"] and metrics["known_members"] and metrics["weekly_active_members"] / metrics["known_members"] < 0.1:
        notes.append("التفاعل المسجل منخفض مقارنة بالأعضاء المعروفين لدى البوت؛ هذه النسبة تقديرية وليست نسبة تيليجرام الرسمية.")
    if not notes:
        notes.append("لا توجد إشارة واضحة من المؤشرات المجمعة وحدها تستدعي إجراءً عاجلًا.")
    return "\n".join("• " + x for x in notes)


async def send_group_analysis_report(bot, recipient_id, only_chat_id=None):
    groups = db.execute("SELECT chat_id,title FROM watched_groups ORDER BY title").fetchall()
    if only_chat_id is not None:
        groups = [row for row in groups if row[0] == only_chat_id]
    # Per-group analysis switch is independent from message protection and basic membership notices.
    groups = [row for row in groups if group_feature_enabled(row[0], "analysis_enabled")]
    if not is_owner(recipient_id):
        allowed = capability_group_ids(recipient_id, "ai")
        groups = [row for row in groups if row[0] in allowed]
    if not groups:
        await bot.send_message(chat_id=recipient_id, text="لا توجد قروبات مسجلة لتحليلها.")
        return
    for chat_id, title in groups[:30]:
        metrics = _group_report_metrics(chat_id, title)
        ai_text = await _ai_analyze_group_metrics(metrics)
        insights = ai_text or _local_group_insights(metrics)
        source_label = ("تحليل ذكاء اصطناعي للمؤشرات المجمعة" if ai_text else
                        ("تحليل محلي احتياطي (تعذر الاتصال بالذكاء الاصطناعي)" if OPENAI_API_KEY else "تحليل محلي للمؤشرات (أضف OPENAI_API_KEY لتفعيل التحليل التوليدي)"))
        report = (
            f"🧠 تقرير تحليل القروب\n\n👥 القروب: {metrics['title']}\n🆔 {chat_id}\n"
            f"💬 الرسائل المرصودة هذا الأسبوع: {metrics['weekly_messages']}\n"
            f"🗣️ الأعضاء المتفاعلون هذا الأسبوع: {metrics['weekly_active_members']}\n"
            f"👤 الأعضاء المعروفون لدى البوت: {metrics['known_members']}\n"
            f"➕ دخول هذا الأسبوع: {metrics.get('weekly_joins', 0)} | ➖ مغادرة: {metrics.get('weekly_leaves', 0)}\n"
            f"🛡️ حالة الحماية: " + ("، ".join(k for k, v in metrics.get('protection_state', {}).items() if v) or "لم يتم تفعيل قيود من القائمة") + "\n"
            f"🧾 العمليات المسجلة آخر 24 ساعة: {metrics['recent_admin_actions_24h']}\n"
            f"🛡️ إجراءات شبيهة بالمخالفات آخر 24 ساعة: {metrics['incident_like_actions_24h']}\n"
            f"📈 حسابات تجاوزت 100 رسالة هذا الأسبوع: {metrics.get('high_activity_members_100plus_messages', 0)}\n"
            f"⚠️ أعضاء لديهم مخالفات مسجلة مؤخرًا: {metrics.get('members_with_recent_violations', 0)} | الإنذارات: {metrics.get('recent_warning_total', 0)}\n"
            f"📌 أكثر أنواع العمليات: " + (", ".join(f"{x['action']} ({x['count']})" for x in metrics['action_breakdown']) or "لا توجد عمليات مسجلة") +
            f"\n\n🔎 {source_label}\n{insights}\n\nℹ️ التقرير مبني على بيانات البوت المرصودة فقط، ولا يثبت المخالفة أو يعكس سجل تيليجرام التاريخي الكامل."
        )
        try:
            await bot.send_message(chat_id=recipient_id, text=report[:3900])
        except Exception as exc:
            log.info("Could not deliver group analysis to %s: %s", recipient_id, exc)
        await asyncio.sleep(0.1)


async def groupreport_cmd(update, context):
    uid = update.effective_user.id if update.effective_user else 0
    if not (is_owner(uid) or can_use_capability(uid, "ai") or capability_group_ids(uid, "ai")):
        await update.effective_message.reply_text("⛔ تحتاج إلى صلاحية تحليل القروبات من المالك."); return
    only_chat_id = None
    if context.args:
        try: only_chat_id = int(context.args[0])
        except ValueError:
            await update.effective_message.reply_text("الاستخدام: /groupreport أو /groupreport CHAT_ID"); return
    if not is_owner(uid):
        allowed_ids = capability_group_ids(uid, "ai")
        if only_chat_id is not None and only_chat_id not in allowed_ids:
            await update.effective_message.reply_text("⛔ لا تملك صلاحية تحليل هذا القروب."); return
        if only_chat_id is None:
            await update.effective_message.reply_text("⏳ جارٍ إعداد تقارير القروبات المصرح بها...")
            for allowed_id in sorted(allowed_ids)[:30]:
                await send_group_analysis_report(context.bot, uid, allowed_id)
            return
    await update.effective_message.reply_text("⏳ جارٍ إعداد التقرير...")
    await send_group_analysis_report(context.bot, uid, only_chat_id)


